edges = [(3,15), (11,13), (13,17), (2,11), (11,17), (2,12), (7,17), (9,17), (3,5), (0,16), (1,14), (7,9), (0,9), (6,11), (3,11), (0,2), (1,17), (4,8), (5,15), (1,15), (2,15), (15,17), (4,16), (0,8), (4,6), (8,13), (13,14), (2,10), (6,13), (9,12)]
edges = [tuple(sorted(e)) for e in edges]
degrees = {i: 0 for i in range(18)}
for u, v in edges:
    degrees[u] += 1
    degrees[v] += 1

import networkx as nx
G = nx.Graph()
G.add_nodes_from(range(18))
G.add_edges_from(edges)

# Add edges to make min degree >= 5
for i in range(18):
    while G.degree(i) < 5:
        for j in range(18):
            if i != j and not G.has_edge(i, j):
                G.add_edge(i, j)
                break

print(list(G.edges()))
